 async function submitDoc(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const data=Object.fromEntries(new FormData(e.currentTarget)) as any;try{if(data.issueDate&&data.issueDate>data.expiry)throw new Error(c('La date de délivrance doit précéder l’expiration.','Issue date must precede expiry.'));if(demo){setDocs(old=>editDoc?old.map(d=>d.id===editDoc.id?{...editDoc,...data}:d):[...old,{...data,id:crypto.randomUUID()}]);}else{await request('/api/documents','POST',{...data,id:editDoc?.id});await load();}setModal('');showToast(demo?c('Document d’exemple enregistré.','Example document saved.'):c('Document enregistré sur cet appareil.','Document saved in this browser.','文件已保存。'));}catch(e){showToast((e as Error).message);}finally{setBusy(false);}}
