 function calendar(){if(!activeDocs.length){showToast(c('Ajoutez un document pour exporter les rappels.','Add a document to export reminders.'));return;}const esc=(s:string)=>s.replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//XidianHub//XieVisas//FR','CALSCALE:GREGORIAN'];activeDocs.forEach(d=>{lines.push('BEGIN:VEVENT',`UID:${d.id}-${d.expiry}@xidianhub.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${d.expiry.replaceAll('-','')}`,`SUMMARY:${esc('Xie-Visas · '+docTitle(d))}`,'DESCRIPTION:Check your document and contact ISO before expiry.');[30,15,7,1].forEach(n=>lines.push('BEGIN:VALARM',`TRIGGER:-P${n}D`,'ACTION:DISPLAY',`DESCRIPTION:Document expires in ${n} days`,'END:VALARM'));lines.push('END:VEVENT');});lines.push('END:VCALENDAR');download(lines.join('\r\n'),'Xie-Visas-rappels.ics','text/calendar');showToast(c('Importez le fichier dans votre calendrier pour activer les rappels.','Import the file into your calendar to enable reminders.'));}
