 function docCard(d:Doc){const n=remainingDays(d.expiry);return <article className="doc-card reveal" key={d.id}><div className="row between"><span className={'document-icon '+urgency(n)}><Icon name={d.type==='residence'?'shield':d.type==='passport'?'globe':d.type==='insurance'?'plus':'file'} size={24}/></span><span className={'status '+urgency(n)}><span/>{status(n)}</span></div><h3>{docTitle(d)}</h3><p className="muted small">{d.label!==docTitle(d)?d.label:c('Expiration le','Expires on','到期日期')} {date(d.expiry)}</p><div className="doc-count"><strong>{Math.abs(n)}</strong><span>{n<0?c('jours de retard','days overdue','逾期天数'):t('days')}</span></div><div className="progress"><i className={urgency(n)} style={{width:Math.max(3,Math.min(100,n/365*100))+'%'}}/></div><button className="text-button" onClick={()=>{setEditDoc(d);setModal('document');}}>{c('Gérer ce document','Manage document','管理文件')}<Icon name="arrow" size={16}/></button></article>}
